raw=zlib.decompress(base64.b64decode(PAYLOAD))
assert H(raw)=='a427e865905b192357b5b92a7e64d998c031aae672c252e974630d59b475cceb'
root=pathlib.Path(sys.argv[1]).resolve()
changes=json.loads(raw)
for name,change in changes.items():
    path=root/name
    old=path.read_bytes() if path.exists() else b''
    assert (H(old) if path.exists() else None)==change['before'],name
    lines=old.decode().splitlines(keepends=True)
    for i,j,v in reversed(change['ops']):lines[i:j]=v
    new=''.join(lines).encode()
    assert H(new)==change['after'],name
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_bytes(new)
print('PASS QA exact candidate delta',len(changes))
